 JSONObject book(){if(state==null)return null;JSONArray bs=state.optJSONArray("books");if(bs!=null)for(int i=0;i<bs.length();i++){JSONObject b=bs.optJSONObject(i);if(b!=null&&b.optString("id").equals(bookId))return b;}return null;}
 JSONObject chapter(){if(state==null)return null;JSONArray cs=state.optJSONArray("chapters");if(cs!=null){for(int i=0;i<cs.length();i++){JSONObject c=cs.optJSONObject(i);if(c!=null&&c.optString("id").equals(chapterId))return c;}if(cs.length()>0)return cs.optJSONObject(cs.length()-1);}return null;}
 JSONObject job(){JSONArray js=state==null?null:state.optJSONArray("jobs");if(js!=null)for(int i=0;i<js.length();i++){JSONObject j=js.optJSONObject(i);if(j!=null&&j.optString("bookId").equals(bookId))return j;}return null;}
 String q(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return "";}}
 JSONObject obj(Object... kv){JSONObject x=new JSONObject();try{for(int i=0;i<kv.length;i+=2)x.put((String)kv[i],kv[i+1]);}catch(Exception ignored){}return x;}
 byte[] request(String path,JSONObject data)throws Exception{return requestWith(profile,path,data);}
 byte[] requestWith(JSONObject p,String path,JSONObject data)throws Exception{if(p==null)throw new IOException("请先连接云端");URL url=new URL(p.getString("origin")+path);HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+p.getString("controlToken"));c.setRequestProperty("X-Novel-Server-Id",p.optString("serverId"));c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Connection","close");try{if(data!=null){c.setRequestMethod("POST");c.setDoOutput(true);byte[] b=data.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(b.length);try(OutputStream out=c.getOutputStream()){out.write(b);}}int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null)try(InputStream stream=in){byte[] buf=new byte[8192];int n;while((n=stream.read(buf))!=-1){out.write(buf,0,n);if(out.size()>64000000)throw new IOException("响应过大");}}byte[] bytes=out.toByteArray();if(code<200||code>=300){String message=new String(bytes,"UTF-8");try{message=new JSONObject(message).optString("error",message);}catch(Exception ignored){}throw new IOException("HTTP "+code+"："+message);}return bytes;}finally{c.disconnect();}}
 void work(TextView feedback,Callable<JSONObject> run,Done done){if(busy)return;busy=true;if(feedback!=null)feedback.setText("正在处理…");statusLabel.setText("正在连接云端…");io.execute(()->{try{JSONObject x=run.call();handler.post(()->{busy=false;try{done.run(x);statusLabel.setText("云端已连接 · "+(state==null?"":state.optString("version")));}catch(Exception e){error(feedback,e);}});}catch(Exception e){handler.post(()->{busy=false;error(feedback,e);});}});}
 void error(TextView view,Exception e){for(View input:settingsFields)input.setEnabled(true);String m=e.getMessage()==null?e.toString():e.getMessage();if(view!=null){view.setText(m+"\n输入和已保存原稿保留。写操作未自动重发，请刷新确认云端状态。");view.setTextColor(RED);}statusLabel.setText(m);}
 void action(String action,JSONObject input,JSONObject extra,TextView feedback,Done done){JSONObject x=obj("action",action,"input",input);if(extra!=null){Iterator<String> k=extra.keys();while(k.hasNext()){String n=k.next();try{x.put(n,extra.get(n));}catch(Exception ignored){}}}work(feedback,()->new JSONObject(new String(request("/v2/action",x),"UTF-8")),done);}
 void refresh(boolean render){work(render?statusLabel:null,()->new JSONObject(new String(request("/v2/state"+(bookId.isEmpty()?"":"?book="+q(bookId)),null),"UTF-8")),x->{state=x;if(bookId.isEmpty())bookId=x.optString("selectedId","");if(render||screen.equals("作品"))show();});}
