 void clear(String name){content.removeAllViews();title(name);}
 void connectPage(){clear("连接我的云端");para("云端连接凭证用于控制服务器，和 DeepSeek API Key 是两项不同配置。");originInput=field("服务器 HTTPS 地址",profile==null?"https://novel-factory-cloud-production.up.railway.app":profile.optString("origin"),false);tokenInput=field("云端连接凭证",profile==null?"":profile.optString("controlToken"),false);tokenInput.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView f=feedback();addButton("保存连接并读取服务器",v->{String origin=originInput.getText().toString().trim();String token=tokenInput.getText().toString().trim();try{URI u=new URI(origin);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getRawQuery()!=null||u.getFragment()!=null||!(u.getPath()==null||u.getPath().isEmpty()||u.getPath().equals("/")))throw new Exception("请填写纯HTTPS服务器地址，不带路径或参数");if(token.length()<20)throw new Exception("请填写云端连接凭证");String normalized=origin.endsWith("/")?origin.substring(0,origin.length()-1):origin;JSONObject p=obj("origin",normalized,"controlToken",token);work(f,()->new JSONObject(new String(requestWith(p,"/api/status",null),"UTF-8")),x->{if(x.optInt("protocol")!=2)throw new IOException("服务器尚未升级V2，请保留连接，等待V2部署完成");p.put("serverId",x.getString("serverId"));CloudVault.save(this,p);profile=p;screen="作品";refresh(true);});}catch(Exception e){error(f,e);}});}
 void show(){if(state==null){refresh(true);return;}if(screen.equals("作品"))home();else if(screen.equals("规划"))planPage();else if(screen.equals("正文"))bodyPage();else if(screen.equals("审核"))reviewPage();else if(screen.equals("设置"))settingsPage(false);else if(screen.equals("记录"))logsPage();else if(screen.equals("备份"))backupPage();else connectPage();}
 void selector(){JSONArray bs=state.optJSONArray("books");if(bs==null||bs.length()==0)return;String[] names=new String[bs.length()];int sel=0;for(int i=0;i<names.length;i++){JSONObject b=bs.optJSONObject(i);names[i]=b.optString("title");if(b.optString("id").equals(bookId))sel=i;}Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));sp.setSelection(sel);final int current=sel;sp.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){if(p!=current&&!bs.optJSONObject(p).optString("id").equals(bookId)){bookId=bs.optJSONObject(p).optString("id");chapterId="";refresh(true);}}});content.addView(sp);}
 String stateName(String s){switch(s){case "running":return "正在运行";case "stopped":return "已停止";case "stopped_unknown":return "已停止后续调用 · 在途结果待核对";case "blocked":return "已阻塞，需处理";case "completed":return "本批次已完成";case "accepted":return "已收稿";case "repair":return "等待返修";case "review":return "等待全文审核";case "draft":return "等待写作";default:return s;}}
 void home(){clear("我的作品");selector();JSONObject b=book(),j=job(),c=chapter();if(b!=null){LinearLayout box=card(b.optString("title"));JSONArray cs=state.optJSONArray("chapters");int done=0;for(int i=0;cs!=null&&i<cs.length();i++)if(cs.optJSONObject(i).optString("state").equals("accepted"))done++;cardText(box,"已收稿 "+done+" / "+b.optInt("totalChapters")+" 章 · "+b.optString("platform"));cardText(box,j==null?"当前没有运行任务":stateName(j.optString("state"))+" · "+j.optString("phase","")+"\n本批次累计收稿目标："+j.optInt("target"));if(c!=null)cardText(box,"第"+c.optInt("number")+"章 · "+c.optInt("words")+"汉字 · 有效审核"+c.optInt("reviewCount")+"/5");if(j!=null&&!j.isNull("error"))cardText(box,j.optString("error"));if(j!=null)cardText(box,"最近保存："+j.optString("lastSavedAt","尚无")+"\n心跳："+state.optString("heartbeat","等待"));
 label("本批次新增章节数（默认1章验收）");EditText count=input(content,"1","1",false);count.setInputType(InputType.TYPE_CLASS_NUMBER);CheckBox latest=new CheckBox(this);latest.setText("明确采用当前已保存模型配置（原任务保留原快照）");content.addView(latest);TextView f=feedback();label("正文1次＋审核1次；每轮返修1次＋复审1次，最多五审。首批/滚动规划另计1次，边界每5章显示。金额仅记账。下一规划边界："+(nextBoundary(b))+"章。");addButton("开始 / 继续云端创作",v->{try{int n=Integer.parseInt(count.getText().toString());action("start",obj("count",n,"useLatest",latest.isChecked()),obj("bookId",bookId),f,x->refresh(true));}catch(Exception e){error(f,e);}});addButton("停止任务",v->action("stop",obj(),obj("bookId",bookId),f,x->refresh(true)));para("退出App、断网或关机不等于停止。停止先阻止后续请求；供应商已经接收的请求仍可能执行或计费。");}
 addButton("刷新真实进度",v->refresh(true));addButton("＋ 创建新作品",v->createPage());}
 int nextBoundary(JSONObject b){JSONObject plan=b.optJSONObject("plan");JSONArray os=plan==null?null:plan.optJSONArray("outlines");int max=0;for(int i=0;os!=null&&i<os.length();i++)max=Math.max(max,os.optJSONObject(i).optInt("number"));return max+1;}
 void createPage(){clear("创建原创作品");EditText t=field("书名","",false),d=field("创作方向：人物、利益、冲突、想兑现的阅读体验","",true),p=field("目标平台（每本锁定一个）","起点",false),n=field("总章节数","100",false),w=field("每章目标汉字","9000",false),style=field("文风要求（可空）","",true);n.setInputType(2);w.setInputType(2);TextView f=feedback();para("投稿规则待核实也可先创作和导出。签约与收入由实际平台决定。");addButton("保存作品（0次模型调用）",v->{try{JSONObject x=obj("id",createId,"title",t.getText().toString(),"direction",d.getText().toString(),"platform",p.getText().toString(),"totalChapters",Integer.parseInt(n.getText().toString()),"targetHan",Integer.parseInt(w.getText().toString()),"style",style.getText().toString());action("create",x,null,f,r->{bookId=r.getJSONObject("result").getString("id");createId=UUID.randomUUID().toString();screen="作品";refresh(true);});}catch(Exception e){error(f,e);}});}
 void chooseChapter(){JSONArray cs=state.optJSONArray("chapters");if(cs==null||cs.length()==0)return;String[] labels=new String[cs.length()];int selected=cs.length()-1;for(int i=0;i<cs.length();i++){JSONObject c=cs.optJSONObject(i);labels[i]="第"+c.optInt("number")+"章 "+c.optString("title","");if(c.optString("id").equals(chapterId))selected=i;}chapterId=cs.optJSONObject(selected).optString("id");Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));sp.setSelection(selected);sp.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int i,long id){String next=cs.optJSONObject(i).optString("id");if(!next.equals(chapterId)){chapterId=next;show();}}});content.addView(sp);}
 void planPage(){clear("方向与滚动规划");selector();JSONObject b=book();if(b==null){para("先创建作品。");return;}para("平台："+b.optString("platform")+"\n方向："+b.optString("direction")+"\n每章 "+b.optInt("minHan")+"—"+b.optInt("maxHan")+" 汉字\n文风："+b.optString("style","")+"\n下一规划边界：第"+nextBoundary(b)+"章（独立一次请求）");addButton("导入本人TXT参考（0模型请求）",v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,103);});JSONObject plan=b.optJSONObject("plan");if(plan==null){para("尚未规划。开始创作后先进行1次全书骨架＋首批约5章规划。");return;}TextView f=feedback();EditText json=field("当前规划JSON（只允许修改未开始章节）",pretty(plan),true);addButton("保存未来规划（0次模型调用）",v->{try{action("planSave",obj("baseHash",b.optString("planHash",sha(plan.toString())),"plan",new JSONObject(json.getText().toString())),obj("bookId",bookId),f,x->refresh(true));}catch(Exception e){error(f,e);}});addButton("导入本人TXT作叙述参考（不调用模型）",v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,103);});}
 String pretty(Object x){try{if(x instanceof JSONObject)return ((JSONObject)x).toString(2);if(x instanceof JSONArray)return ((JSONArray)x).toString(2);}catch(Exception ignored){}return String.valueOf(x);}
 String sha(String x){try{byte[] b=java.security.MessageDigest.getInstance("SHA-256").digest(x.getBytes("UTF-8"));StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}catch(Exception e){return "";}}
 void bodyPage(){clear("正文与版本");selector();chooseChapter();JSONObject c=chapter();if(c==null){para("尚无章节正文。");return;}para("当前稿 "+c.optInt("words")+"汉字 · "+stateName(c.optString("state"))+"\n正文hash："+c.optString("hash","")+"\n有效审核 "+c.optInt("reviewCount")+"/5");EditText bodyInput=field("当前正文",c.optString("body",""),true);bodyInput.setMinLines(12);editorBaseHash=c.optString("hash","");if(c.optString("state").equals("accepted"))bodyInput.setEnabled(false);TextView f=feedback();if(!c.optString("state").equals("accepted"))addButton("保存人工修改（0次模型调用）",v->action("edit",obj("baseHash",c.isNull("hash")?JSONObject.NULL:editorBaseHash,"body",bodyInput.getText().toString()),obj("chapterId",c.optString("id")),f,x->refresh(true)));else label("该章已收稿，保留原稿；人工精修需另建明确编辑任务，不清零五审次数。");addButton("读取历史稿和审核版本",v->work(f,()->new JSONObject(new String(request("/v2/versions?chapter="+q(c.optString("id")),null),"UTF-8")),x->{JSONArray versions=x.optJSONArray("versions");if(versions==null||versions.length()==0){f.setText("无历史稿");return;}String[] names=new String[versions.length()];for(int k=0;k<names.length;k++)names[k]="#"+(k+1)+" "+versions.optJSONObject(k).optJSONObject("data").optString("source")+" · "+versions.optJSONObject(k).optString("hash").substring(0,10);new AlertDialog.Builder(this).setTitle("历史正文（只读）").setItems(names,(d,n)->{EditText read=new EditText(this);read.setText(versions.optJSONObject(n).optString("body"));read.setTextIsSelectable(true);new AlertDialog.Builder(this).setTitle(names[n]).setView(read).setPositiveButton("关闭",null).show();}).show();}));addButton("导出全书TXT",v->export("/v2/export?book="+q(bookId),"NovelFactory-正文.txt","text/plain",f));}
 void reviewPage(){clear("审核与返修");selector();chooseChapter();JSONObject c=chapter();if(c==null){para("尚无审核。");return;}JSONObject r=c.optJSONObject("review");if(r==null)r=c.optJSONObject("legacyReview");para("第"+c.optInt("number")+"章 · 有效全文审核 "+c.optInt("reviewCount")+"/5\n"+c.optString("release",stateName(c.optString("state"))));if(r!=null){if(r.has("total"))title(r.optInt("total")+" / 100");para(pretty(r));}else para("还没有完成的全文审核。失败请求不计有效次数。");if(c.has("diff")){title("本轮实际修改");para(pretty(c.optJSONArray("diff")));}TextView f=feedback();if(c.optInt("reviewCount")<5&&!c.optString("state").equals("accepted"))addButton("按意见返修并复审（云端任务）",v->action("start",obj("count",1),obj("bookId",bookId),f,x->{screen="作品";refresh(true);}));else label("五审已收稿，真实分数保留；不会自动第六审。");}
