 void watch(EditText e){e.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){settingsDirty=true;}public void afterTextChanged(android.text.Editable s){}});}
 void settingsPage(boolean force){clear("模型设置");JSONObject cfg=state.optJSONObject("settings");if(force||settingsDraft==null||!settingsDirty)try{settingsDraft=new JSONObject(cfg.toString());}catch(Exception ignored){}JSONObject d=settingsDraft;settingsFields.clear();roles.clear();para("默认一把DeepSeek密钥由策划、写手、审核共用。价格可空，只记账，不限制创作金额。保存设置0次模型调用。");label("服务商：DeepSeek官方 API");modelInput=field("模型ID（可编辑）",d.optString("model","deepseek-v4-pro"),false);keyInput=field("更新API Key（留空保留云端已存）","",false);keyInput.setInputType(129);label(d.optBoolean("keySaved")?"云端已保存密钥；不会回显。":"云端尚无主密钥。");maxInput=field("最大输出token",d.optString("maxTokens","24000"),false);contextInput=field("模型上下文token容量",d.optString("contextTokens","1000000"),false);tempInput=field("非思考温度0—2",d.optString("temperature","0.8"),false);label("思考模式（非思考适用于正文）");thinkingInput=new Spinner(this);String[] ts={"disabled","low","high","max"};thinkingInput.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ts));for(int i=0;i<ts.length;i++)if(ts[i].equals(d.optString("thinking")))thinkingInput.setSelection(i);content.addView(thinkingInput);authorizedInput=new CheckBox(this);authorizedInput.setText("允许云端按已登记任务调用模型并产生实际API费用");authorizedInput.setChecked(d.optBoolean("authorized"));content.addView(authorizedInput);para("授权保存一次即可；关闭会立即禁止后续调用。正在执行的任务保留原配置快照，停止后可明确勾选采用新配置。");
 LinearLayout advanced=new LinearLayout(this);advanced.setOrientation(1);advanced.setVisibility(View.GONE);addButton("展开 / 收起高级角色和单价",v->advanced.setVisibility(advanced.getVisibility()==View.GONE?View.VISIBLE:View.GONE));content.addView(advanced);JSONObject rs=d.optJSONObject("roles");for(String role:new String[]{"planner","writer","reviewer"}){RoleForm form=new RoleForm();form.independent=new CheckBox(this);form.independent.setText(role+" 使用独立设置");JSONObject rd=rs==null?null:rs.optJSONObject(role);form.independent.setChecked(rd!=null);advanced.addView(form.independent);form.model=input(advanced,role+"模型ID",rd==null?d.optString("model"):rd.optString("model",d.optString("model")),false);form.key=input(advanced,role+"独立Key（留空沿用已存/主Key）","",false);form.key.setInputType(129);roles.put(role,form);settingsFields.add(form.independent);settingsFields.add(form.model);settingsFields.add(form.key);}
 JSONObject prices=d.optJSONObject("prices");advanced.addView(text("每百万token单价（人民币，可空；非供应商发票）",13,MUTED));priceInput=input(advanced,"输入单价",val(prices,"input"),false);cacheInput=input(advanced,"缓存命中单价",val(prices,"cacheHit"),false);missInput=input(advanced,"缓存未命中单价",val(prices,"cacheMiss"),false);outputInput=input(advanced,"输出单价",val(prices,"output"),false);
 TextView f=feedback();Button save=button("保存并回读模型设置",v->{try{JSONObject x=collectSettings();for(View view:settingsFields)view.setEnabled(false);action("settings",x,null,f,r->{for(View view:settingsFields)view.setEnabled(true);JSONObject saved=r.getJSONObject("result");state.put("settings",saved);settingsDraft=new JSONObject(saved.toString());settingsDirty=false;editorDraft=null;keyInput.setText("");for(RoleForm form:roles.values())form.key.setText("");settingsDirty=false;f.setText("云端保存成功 · 配置版本 "+saved.optInt("revision")+"\n本次保存0次模型调用。新的任务采用该版本；已有任务需停止后明确采用。");});}catch(Exception e){for(View view:settingsFields)view.setEnabled(true);error(f,e);}});content.addView(save);
 // Work errors restore inputs; no refresh or polling ever overwrites this page.
 Button reload=button("读取最新配置（保留未保存Key）",v->{String key=keyInput.getText().toString();Map<String,String> pending=new HashMap<>();for(String role:roles.keySet())pending.put(role,roles.get(role).key.getText().toString());work(f,()->new JSONObject(new String(request("/v2/state",null),"UTF-8")),r->{state=r;settingsDirty=false;editorDraft=null;settingsPage(true);keyInput.setText(key);for(String role:pending.keySet())roles.get(role).key.setText(pending.get(role));});});content.addView(reload);addButton("连接测试：明确发送1次供应商请求",v->{new AlertDialog.Builder(this).setTitle("测试已保存配置").setMessage("将发送最多1次DeepSeek请求并记录可能费用；不会保存输入中的未保存Key。任务在云端登记。 ").setNegativeButton("取消",null).setPositiveButton("发送一次测试",(a,b)->{if(testId.isEmpty())testId=UUID.randomUUID().toString();action("test",obj("id",testId),null,f,r->{testId="";f.setText("连接测试已登记。到运行记录查看真实结果。");});}).show();});settingsFields.addAll(Arrays.asList(modelInput,keyInput,maxInput,contextInput,tempInput,thinkingInput,authorizedInput,priceInput,cacheInput,missInput,outputInput));if(editorDraft!=null&&!force){for(Map.Entry<String,EditText> e:formFields().entrySet())e.getValue().setText(editorDraft.optString(e.getKey(),e.getValue().getText().toString()));authorizedInput.setChecked(editorDraft.optBoolean("authorized",authorizedInput.isChecked()));thinkingInput.setSelection(editorDraft.optInt("thinking",thinkingInput.getSelectedItemPosition()));for(String role:roles.keySet()){JSONObject rd=editorDraft.optJSONObject(role);if(rd!=null){RoleForm rf=roles.get(role);rf.model.setText(rd.optString("model"));rf.key.setText(rd.optString("key"));rf.independent.setChecked(rd.optBoolean("independent"));}}}for(EditText e:formFields().values())watch(e);for(RoleForm rf:roles.values()){watch(rf.model);watch(rf.key);rf.independent.setOnCheckedChangeListener((a,b)->settingsDirty=true);}authorizedInput.setOnCheckedChangeListener((a,b)->settingsDirty=true);}
 Map<String,EditText> formFields(){Map<String,EditText> m=new LinkedHashMap<>();m.put("model",modelInput);m.put("key",keyInput);m.put("max",maxInput);m.put("context",contextInput);m.put("temperature",tempInput);m.put("inputPrice",priceInput);m.put("cacheHit",cacheInput);m.put("cacheMiss",missInput);m.put("outputPrice",outputInput);return m;}
 void captureDraft(){if(modelInput==null)return;editorDraft=obj("authorized",authorizedInput.isChecked(),"thinking",thinkingInput.getSelectedItemPosition());try{for(Map.Entry<String,EditText> e:formFields().entrySet())editorDraft.put(e.getKey(),e.getValue().getText().toString());for(String role:roles.keySet()){RoleForm rf=roles.get(role);editorDraft.put(role,obj("model",rf.model.getText().toString(),"key",rf.key.getText().toString(),"independent",rf.independent.isChecked()));}settingsDirty=true;}catch(Exception ignored){}}

 String val(JSONObject o,String key){return o==null||o.isNull(key)?"":o.optString(key,"");}
 void price(JSONObject p,String key,EditText e)throws Exception{String v=e.getText().toString().trim();if(!v.isEmpty())p.put(key,Double.parseDouble(v));}
 JSONObject collectSettings()throws Exception{JSONObject p=new JSONObject();price(p,"input",priceInput);price(p,"cacheHit",cacheInput);price(p,"cacheMiss",missInput);price(p,"output",outputInput);JSONObject rs=new JSONObject();for(String role:roles.keySet()){RoleForm f=roles.get(role);rs.put(role,f.independent.isChecked()?obj("model",f.model.getText().toString().trim(),"apiKey",f.key.getText().toString().trim()):obj("inherit",true));}return obj("revision",settingsDraft.optInt("revision"),"provider","deepseek","model",modelInput.getText().toString().trim(),"apiKey",keyInput.getText().toString().trim(),"maxTokens",Integer.parseInt(maxInput.getText().toString()),"contextTokens",Integer.parseInt(contextInput.getText().toString()),"temperature",Double.parseDouble(tempInput.getText().toString()),"thinking",thinkingInput.getSelectedItem().toString(),"authorized",authorizedInput.isChecked(),"roles",rs,"prices",p.length()==0?JSONObject.NULL:p);}
 void logsPage(){clear("真实请求记录");para("进度轮询和保存设置不在模型请求中。未知费用保留待核对；估算单价不是官方账单。");TextView f=feedback();addButton("刷新请求记录",v->refresh(true));JSONArray a=state.optJSONArray("steps");for(int i=0;a!=null&&i<a.length();i++){JSONObject st=a.optJSONObject(i);LinearLayout c=card(st.optString("phase")+" · "+st.optString("status"));cardText(c,"角色："+st.optString("role")+" · "+st.optString("model")+"\n配置版本："+st.optString("configRevision")+"\n发送意图："+st.optString("intentAt","无")+"\n供应商请求ID："+st.optString("providerRequestId","无")+"\n"+st.optString("amountStatus")+"\n"+st.optString("error",""));cardText(c,"usage："+pretty(st.optJSONObject("usage"))+"\n实际参数："+pretty(st.optJSONObject("parameters")));c.addView(button("查看已保存响应 / 候选",v->work(f,()->new JSONObject(new String(request("/v2/step?key="+q(st.optString("key")),null),"UTF-8")),x->{EditText r=new EditText(this);r.setText(x.optString("raw","暂无响应"));new AlertDialog.Builder(this).setTitle("私人响应（只读）").setView(r).setPositiveButton("关闭",null).show();})));if(st.optString("status").equals("rejected"))c.addView(button("本地重新解析（0次模型请求）",v->action("reparse",obj(),obj("key",st.optString("key")),f,r->refresh(true))));}
 label("旧调用记录保留："+state.optInt("legacyCallCount")+"条。");addButton("查看旧调用关联（私人）",v->work(f,()->new JSONObject(new String(request("/v2/legacy-calls",null),"UTF-8")),x->{EditText read=new EditText(this);read.setText(pretty(x));new AlertDialog.Builder(this).setTitle("旧调用原始关联").setView(read).setPositiveButton("关闭",null).show();}));}
 void backupPage(){clear("备份与恢复");para("完整作品备份含正文、历史稿、审核、任务和调用关联。备份不含模型密钥；恢复默认暂停。云端首次V2切换另保留原库和原保险箱的一致性私有备份。");TextView f=feedback();addButton("导出完整作品备份JSON",v->export("/v2/backup","NovelFactory-V2-Backup.json","application/json",f));addButton("导出当前作品TXT",v->export("/v2/export?book="+q(bookId),"NovelFactory-正文.txt","text/plain",f));addButton("恢复备份（仅空V2库）",v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,102);});addButton("停止全部任务与连接测试",v->action("stopAll",obj(),null,f,r->refresh(true)));label("迁移记录："+pretty(state.optJSONObject("migration")));}
 void export(String path,String name,String mime,TextView f){work(f,()->{pendingExport=request(path,null);return obj("ok",true);},r->{pendingName=name;pendingMime=mime;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,101);});}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(code==101&&pendingExport!=null){try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(pendingExport);pendingExport=null;Toast.makeText(this,"已导出",Toast.LENGTH_SHORT).show();}catch(Exception e){error(statusLabel,e);}}else if(code==102){TextView f=feedback();work(f,()->{byte[] bytes=readUri(uri,64000000);JSONObject x=new JSONObject(new String(bytes,"UTF-8"));return new JSONObject(new String(request("/v2/action",obj("action","restore","input",x)),"UTF-8"));},r->{screen="作品";refresh(true);});}else if(code==103){TextView f=feedback();work(f,()->{String ref=new String(readUri(uri,2000000),"UTF-8");return obj("reference",ref);},r->{String ref=r.optString("reference");new AlertDialog.Builder(this).setTitle("本人TXT参考").setMessage("将保存到私人作品库，本地统计段落、句长、对白比例作为未来章参考，0次模型请求。仅学习方法。\n\n"+ref.substring(0,Math.min(700,ref.length()))).setNegativeButton("取消",null).setPositiveButton("保存参考",(a,b)->action("reference",obj("text",ref),obj("bookId",bookId),f,x->refresh(true))).show();});}}
 byte[] readUri(Uri uri,int limit)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("文件过大");}return out.toByteArray();}}
